import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ClientCacheMissResponse{Blobs: []protocol.CacheBlob{
#   {Hash: 0x0102030405060708, Payload: []byte("chunk")}, {Hash: 300}}}
BLOBS = bytes.fromhex("020807060504030201056368756e6b2c0100000000000000")

# generated by gophertunnel b8bd735:
# &packet.ClientCacheMissResponse{}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# &packet.ClientCacheMissResponse{Blobs: []protocol.CacheBlob{{Hash: 300, Payload: bytes.Repeat([]byte("x"), 200)}}}
LONG_PAYLOAD = bytes.fromhex(
    ""
)

GOLDENS = [
    pytest.param(
        v2225.ClientCacheMissResponsePacket(
            blobs=[
                v2225.MissingBlobData(blob_id=0x0102030405060708, blob_data=b"chunk"),
                v2225.MissingBlobData(blob_id=300, blob_data=b""),
            ]
        ),
        BLOBS,
        id="blobs",
    ),
    pytest.param(v2225.ClientCacheMissResponsePacket(), EMPTY, id="empty"),
    pytest.param(
        v2225.ClientCacheMissResponsePacket(blobs=[v2225.MissingBlobData(blob_id=300, blob_data=b"x" * 200)]),
        LONG_PAYLOAD,
        id="long-payload",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_client_cache_miss_response_is_packet_136(version):
    assert version.packets[136] is version.ClientCacheMissResponsePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_cache_miss_response_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_cache_miss_response_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
